const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{height:100%;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.wrap{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;padding:10px}\n.hd{display:flex;align-items:center;gap:6px;min-width:0;flex:0 0 auto}\n.hd h1{flex:1;min-width:0;margin:0;font-size:15px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.btn{font:inherit;font-size:12px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:8px;padding:6px 10px;min-height:30px;cursor:pointer;white-space:nowrap}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.btn.sm{padding:3px 8px;min-height:26px}\n.link{font:inherit;font-size:12px;background:none;border:0;padding:4px;color:var(--accent);text-decoration:underline;cursor:pointer;white-space:nowrap}\n.link.danger{color:#B4533A;font-weight:600}\n.sumline{display:none;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sumline b{color:var(--ink);font-size:12px}\n.sl-od{color:#B4533A;font-weight:600}\n.tiles{display:none;gap:6px;min-width:0}\n.tile{flex:1;min-width:0;display:flex;flex-direction:column;padding:5px 8px;border-radius:10px;background:var(--soft);border:1px solid var(--line)}\n.t-l{font-size:10px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.t-v{font-size:15px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.t-od{border-left:3px solid #B4533A}\n.t-sn{border-left:3px solid var(--accent)}\n.fbar{display:none;gap:4px;flex:0 0 auto}\n.flt{flex:1;min-width:0;font:inherit;font-size:11px;padding:4px 2px;border:1px solid var(--line);border-radius:999px;background:transparent;color:var(--ink);cursor:pointer;white-space:nowrap}\n.flt.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:6px}\n.empty{margin:auto;text-align:center;color:var(--muted);display:flex;flex-direction:column;align-items:center;gap:8px;padding:8px}\n.empty p{margin:0}\n.row{flex:0 0 auto;width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:8px;row-gap:4px;align-items:center;text-align:left;font:inherit;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;padding:7px 9px;cursor:pointer}\n.row.st-overdue{border-left:3px solid #B4533A}\n.row.st-soon{border-left:3px solid var(--accent)}\n.row.st-done{background:transparent}\n.r-l{min-width:0}\n.r-1{display:flex;align-items:center;gap:5px;min-width:0}\n.r-c{min-width:0;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.r-2{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.r-r{display:flex;flex-direction:column;align-items:flex-end;gap:3px}\n.r-amt{font-weight:700;white-space:nowrap}\n.r-bar{grid-column:1/3;display:none;align-items:center;gap:8px}\n.r-note{font-size:10px;color:var(--muted);white-space:nowrap}\n.chip{font-size:10px;line-height:1;padding:3px 6px;border-radius:999px;white-space:nowrap;border:1px solid var(--line);color:var(--muted)}\n.chip.c-overdue{background:#B4533A;border-color:#B4533A;color:#FFFFFF;font-weight:600}\n.chip.c-soon{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.tag{flex:0 0 auto;font-size:9.5px;line-height:1;padding:2px 5px;border-radius:5px;white-space:nowrap}\n.t-yes{border:1px solid var(--accent);color:var(--accent)}\n.t-no{border:1px dashed var(--muted);color:var(--muted)}\n.bar{flex:1;height:6px;border-radius:99px;background:var(--soft);border:1px solid var(--line);overflow:hidden}\n.bar i{display:block;height:100%;background:var(--accent)}\n.bar.big{flex:0 0 auto;height:9px}\n\n/* 3x3 */\n.card[data-size=\"3x3\"] .sumline{display:block}\n.card[data-size=\"3x3\"] .row{padding:6px 8px}\n.card[data-size=\"3x3\"] .r-c{font-size:12.5px}\n/* 6x3 */\n.card[data-size=\"6x3\"] .v-list{display:grid;grid-template-columns:130px minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);column-gap:10px}\n.card[data-size=\"6x3\"] .v-list .hd{grid-column:1;grid-row:1}\n.card[data-size=\"6x3\"] .v-list .hd .btn{padding:3px 6px}\n.card[data-size=\"6x3\"] .v-list .tiles{display:flex;flex-direction:column;gap:4px;grid-column:1;grid-row:2;min-height:0;overflow:hidden}\n.card[data-size=\"6x3\"] .v-list .tile{flex:0 0 auto;padding:3px 8px}\n.card[data-size=\"6x3\"] .v-list .t-v{font-size:14px}\n.card[data-size=\"6x3\"] .v-list .list{grid-column:2;grid-row:1/3}\n.card[data-size=\"6x3\"] .r-bar,.card[data-size=\"3x6\"] .r-bar,.card[data-size=\"6x6\"] .r-bar{display:flex}\n.card[data-size=\"3x6\"] .r-note{display:none}\n/* 3x6 */\n.card[data-size=\"3x6\"] .tiles{display:grid;grid-template-columns:1fr 1fr}\n.card[data-size=\"3x6\"] .t-all{grid-column:1/3}\n.card[data-size=\"3x6\"] .fbar,.card[data-size=\"6x6\"] .fbar{display:flex}\n/* 6x6 */\n.card[data-size=\"6x6\"] .tiles{display:flex}\n.card[data-size=\"6x6\"] .wrap{padding:14px;gap:10px}\n.card[data-size=\"6x6\"] .row{padding:9px 12px}\n.card[data-size=\"6x6\"] .r-c{font-size:14px}\n.card[data-size=\"6x6\"] .r-amt{font-size:15px}\n/* \u8be6\u60c5\u4e0e\u8868\u5355 */\n.body{flex:1;min-height:0;min-width:0;overflow-y:auto;display:flex;flex-direction:column;gap:8px}\n.dcols{display:flex;flex-direction:column;gap:8px;min-width:0;flex:0 0 auto}\n.card[data-size=\"6x3\"] .body.det,.card[data-size=\"6x6\"] .body.det{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;overflow:hidden}\n.card[data-size=\"6x3\"] .body.det .dcols,.card[data-size=\"6x6\"] .body.det .dcols{overflow-y:auto;min-height:0}\n.proj{color:var(--muted);font-size:12px;overflow-wrap:anywhere}\n.kvs{display:grid;grid-template-columns:1fr;gap:4px}\n.kv{display:flex;justify-content:space-between;align-items:center;gap:8px;background:var(--soft);border-radius:8px;padding:4px 8px;min-width:0}\n.k{font-size:11px;color:var(--muted);white-space:nowrap}\n.v{font-weight:650;display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:center;gap:4px;min-width:0;white-space:nowrap}\n.kv.strong .v{font-size:14px}\n.card[data-size=\"6x6\"] .kvs{grid-template-columns:1fr 1fr}\n.card[data-size=\"6x6\"] .kv{flex-direction:column;align-items:flex-start;padding:6px 10px}\n.card[data-size=\"6x6\"] .v{justify-content:flex-start}\n.invrow{display:flex;align-items:center;justify-content:space-between;gap:6px}\n.card h2{margin:0;font-size:12px;font-weight:600;color:var(--muted)}\n.muted{margin:0;color:var(--muted);font-size:12px}\n.pays{display:flex;flex-direction:column}\n.pay{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:6px;align-items:center;padding:4px 0;border-bottom:1px solid var(--line)}\n.p-l{display:flex;flex-direction:column;min-width:0}\n.p-d{font-size:12px;white-space:nowrap}\n.p-n{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.p-a{font-weight:700;white-space:nowrap}\n.dz{padding-top:4px}\n.foot{display:flex;gap:6px;flex:0 0 auto}\n.foot .btn{flex:1;min-width:0}\n.foot .btn.primary{flex:2}\n.fields{display:grid;grid-template-columns:1fr;gap:8px}\n.card[data-size=\"6x3\"] .fields,.card[data-size=\"6x6\"] .fields{grid-template-columns:1fr 1fr}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fld.wide{grid-column:1/-1}\n.fld.chk{flex-direction:row;align-items:center;gap:8px}\n.fl{font-size:11px;color:var(--muted)}\n.inp{font:inherit;font-size:13px;width:100%;min-width:0;min-height:32px;padding:5px 8px;color:var(--ink);background:var(--panel-paper);border:1px solid var(--line);border-radius:8px}\n.err{margin:0;color:#B4533A;font-weight:600;font-size:12px}\n.ctx{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:12px;color:var(--muted)}\n.ctx span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n";
function r2(n){return Math.round(Number(n)*100)/100}
function fmt(n){
  const neg=n<0;const c=Math.abs(Math.round(n*100));
  const y=Math.floor(c/100),f=c%100;
  const s=String(y).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  return (neg?'-':'')+'¥'+s+(f?'.'+(f<10?'0':'')+f:'');
}
function fmtS(n){
  if(Math.abs(n)>=100000)return '¥'+(Math.round(n/1000)/10)+'万';
  return fmt(n);
}
function dnum(s){const a=String(s||'').split('-');return Math.round(Date.UTC(+a[0],(+a[1])-1,+a[2])/86400000)}
function dshort(s){const a=String(s||'').split('-');return a.length===3?(+a[1])+'月'+(+a[2])+'日':String(s||'')}
function dfull(s){const a=String(s||'').split('-');return a.length===3?(+a[0])+'年'+(+a[1])+'月'+(+a[2])+'日':String(s||'')}
function calc(it,today){
  let c=0;
  (it.payments||[]).forEach(function(p){c+=Math.round(Number(p.amount||0)*100)});
  const r=c/100;
  const rem=Math.max(0,(Math.round(Number(it.amount)*100)-c)/100);
  const d=dnum(it.due)-dnum(today);
  const st=rem<=0?'done':(d<0?'overdue':(d<=7?'soon':'wait'));
  return {it:it,r:r,rem:rem,d:d,st:st};
}
function rank(st){return st==='overdue'?0:(st==='soon'?1:(st==='wait'?2:3))}
function statusText(x){
  if(x.st==='done')return '已收齐';
  if(x.st==='overdue')return '逾期'+(-x.d)+'天';
  if(x.st==='soon')return x.d===0?'今天到期':x.d+'天后到期';
  return '待收';
}
function sortCalc(list){
  return list.slice().sort(function(a,b){
    if(a.st!==b.st)return rank(a.st)-rank(b.st);
    const da=dnum(a.it.due),db=dnum(b.it.due);
    return a.st==='done'?db-da:da-db;
  });
}
function sumRem(arr){return arr.reduce(function(a,x){return a+Math.round(x.rem*100)},0)/100}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const today=day();
  const items=(state&&state.items)||[];
  if(!ui.view)ui.view='list';
  if(!ui.filter)ui.filter='all';
  const nu=(x)=>Object.assign({view:'list',id:null,draft:null,err:'',confirm:null,busy:false,filter:ui.filter||'all'},x||{});
  const go=(x)=>{Object.assign(ui,nu(x));redraw()};
  const E=(tag,a,...k)=>el(tag,typeof a==='string'?{class:a}:(a||{}),...k.flat().filter(v=>v!==null&&v!==undefined&&v!==false));
  const btn=(label,cls,fn,more)=>E('button',Object.assign({class:cls,type:'button',onclick:fn},more||{}),label);
  const cs=sortCalc(items.map(it=>calc(it,today)));
  const open=cs.filter(x=>x.st!=='done');
  const od=open.filter(x=>x.st==='overdue');
  const sn=open.filter(x=>x.st==='soon');

  const openNew=()=>go({view:'form',id:null,draft:{_id:uid(),client:'',project:'',amount:'',due:'',invoiced:false}});
  const openEdit=(it)=>go({view:'form',id:it.id,draft:{client:it.client,project:it.project||'',amount:String(it.amount),due:it.due,invoiced:!!it.invoiced}});
  const openPay=(it)=>go({view:'pay',id:it.id,draft:{_id:uid(),date:today,amount:'',note:''}});

  const chip=(x)=>E('span','chip c-'+x.st,statusText(x));
  const inv=(it)=>E('span','tag '+(it.invoiced?'t-yes':'t-no'),it.invoiced?'已开票':'未开票');
  const bar=(x,cls)=>{
    const pct=x.it.amount>0?Math.min(100,Math.round(x.r/x.it.amount*100)):0;
    const fill=E('i');
    fill.style.width=pct+'%';
    return E('div','bar'+(cls?' '+cls:''),fill);
  };

  const row=(x)=>{
    const it=x.it;
    return E('button',{class:'row st-'+x.st,type:'button',onclick:()=>go({view:'detail',id:it.id})},
      E('div','r-l',
        E('div','r-1',E('span','r-c',it.client),inv(it)),
        E('div','r-2',(it.project?it.project+' · ':'')+'到期 '+dshort(it.due))),
      E('div','r-r',E('div','r-amt',fmtS(x.st==='done'?it.amount:x.rem)),chip(x)),
      E('div','r-bar',bar(x),E('span','r-note','已收 '+fmtS(x.r)+' / '+fmtS(it.amount))));
  };

  const tile=(label,val,cls)=>E('div','tile '+cls,E('span','t-l',label),E('span','t-v',val));

  function listView(){
    const doneN=cs.length-open.length;
    const shown=ui.filter==='open'?open:(ui.filter==='done'?cs.filter(x=>x.st==='done'):cs);
    const fl=(k,label,n)=>btn(label+' '+n,'flt'+(ui.filter===k?' on':''),()=>{ui.filter=k;redraw()},{'aria-pressed':String(ui.filter===k)});
    const empty=items.length
      ?E('div','empty',E('p',null,'没有符合条件的记录'))
      :E('div','empty',E('p',null,'还没有收款记录'),btn('记录第一笔应收','btn primary',openNew));
    return E('div','wrap v-list',
      E('div','hd',E('h1',null,'收款跟踪'),btn('+ 新增','btn primary sm',openNew)),
      E('div','sumline','待收 ',E('b',null,fmtS(sumRem(open))),od.length?E('span','sl-od',' · 逾期 '+od.length+' 笔'):null),
      E('div','tiles',
        tile('待收合计',fmtS(sumRem(open)),'t-all'),
        tile('逾期 '+od.length+' 笔',fmtS(sumRem(od)),'t-od'),
        tile('7天内到期 '+sn.length+' 笔',fmtS(sumRem(sn)),'t-sn')),
      E('div','fbar',fl('all','全部',cs.length),fl('open','未收齐',open.length),fl('done','已收齐',doneN)),
      E('div','list',shown.length?shown.map(row):empty));
  }


  const kv=(k,v,cls)=>E('div','kv '+(cls||''),E('span','k',k),E('span','v',v));
  const patchItem=(id,fn)=>update(s=>Object.assign({},s,{items:((s&&s.items)||[]).map(i=>i.id===id?fn(i):i)})).catch(()=>{});

  function detail(x){
    const it=x.it;
    const pays=(it.payments||[]).slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)));
    const payRows=pays.map(p=>{
      const ck='p:'+p.id;
      const asking=ui.confirm===ck;
      return E('div','pay',
        E('div','p-l',E('span','p-d',dfull(p.date)),p.note?E('span','p-n',p.note):null),
        E('span','p-a',fmt(p.amount)),
        btn(asking?'确认删除':'删除','link'+(asking?' danger':''),()=>{
          if(!asking){ui.confirm=ck;redraw();return}
          ui.confirm=null;
          patchItem(it.id,i=>Object.assign({},i,{payments:(i.payments||[]).filter(q=>q.id!==p.id)}));
        }));
    });
    const delAsking=ui.confirm==='del';
    const colA=E('div','dcols',
      it.project?E('div','proj',it.project):null,
      E('div','kvs',
        kv('约定金额',fmt(it.amount)),
        kv('已收',fmt(x.r)),
        kv('未收',fmt(x.rem),'strong'),
        kv('到账日期',[dfull(it.due),chip(x)])),
      bar(x,'big'),
      E('div','invrow',inv(it),
        btn(it.invoiced?'改为未开票':'标为已开票','link',()=>patchItem(it.id,i=>Object.assign({},i,{invoiced:!i.invoiced})))));
    const colB=E('div','dcols',
      E('h2',null,'收款记录 · '+pays.length+' 笔'),
      pays.length?E('div','pays',payRows):E('p','muted','还没有分次收款记录'),
      E('div','dz',btn(delAsking?'确认删除这条应收':'删除这条应收','link danger',()=>{
        if(!delAsking){ui.confirm='del';redraw();return}
        ui.confirm=null;ui.view='list';ui.id=null;
        update(s=>Object.assign({},s,{items:((s&&s.items)||[]).filter(i=>i.id!==it.id)})).catch(()=>{ui.view='detail';ui.id=it.id;redraw()});
      })));
    return E('div','wrap v-detail',
      E('div','hd',btn('‹ 返回','btn sm',()=>go()),E('h1',null,it.client)),
      E('div','body det',colA,colB),
      E('div','foot',x.rem>0?btn('记一笔收款','btn primary',()=>openPay(it)):null,btn('编辑','btn',()=>openEdit(it))));
  }


  function fieldEl(f,onEnter){
    const d=ui.draft;
    if(f.type==='checkbox'){
      return E('label','fld chk wide',E('input',{type:'checkbox',checked:!!d[f.key],onchange:(e)=>{d[f.key]=e.target.checked}}),E('span',null,f.label));
    }
    const attrs={type:f.type||'text',class:'inp',value:d[f.key]==null?'':String(d[f.key]),
      oninput:(e)=>{d[f.key]=e.target.value},onchange:(e)=>{d[f.key]=e.target.value},
      onkeydown:(e)=>{if(e.key==='Enter')onEnter()}};
    if(f.ph)attrs.placeholder=f.ph;
    if(f.step)attrs.step=f.step;
    if(f.min!=null)attrs.min=f.min;
    if(f.type==='number')attrs.inputmode='decimal';
    return E('label','fld'+(f.wide?' wide':''),E('span','fl',f.label+(f.req?' *':'')),E('input',attrs));
  }

  function formFrame(title,fields,onSave,onBack,extra){
    return E('div','wrap v-form',
      E('div','hd',btn('‹ 返回','btn sm',onBack),E('h1',null,title)),
      E('div','body',extra,E('div','fields',fields.map(f=>fieldEl(f,onSave))),
        ui.err?E('p',{class:'err',role:'alert'},'⚠ '+ui.err):null),
      E('div','foot',btn('取消','btn',onBack),btn('保存','btn primary',onSave)));
  }

  function saveItem(){
    if(ui.busy)return;
    const d=ui.draft;
    const client=String(d.client||'').trim(),project=String(d.project||'').trim();
    const amount=r2(d.amount),due=String(d.due||'');
    let err='';
    if(!client)err='请填写客户';
    else if(!(amount>0))err='约定金额要大于 0';
    else if(!/^\d{4}-\d{2}-\d{2}$/.test(due))err='请选择到账日期';
    if(err){ui.err=err;redraw();return}
    ui.busy=true;
    const id=ui.id||d._id,invoiced=!!d.invoiced,editing=!!ui.id;
    commit(s=>{
      const list=(s&&s.items)||[];
      const exists=list.some(i=>i.id===id);
      const next=exists
        ?list.map(i=>i.id===id?Object.assign({},i,{client,project,amount,due,invoiced}):i)
        :list.concat([{id,client,project,amount,due,invoiced,payments:[]}]);
      return Object.assign({},s,{items:next});
    },nu(editing?{view:'detail',id}:{})).catch(()=>{ui.busy=false;ui.err='保存失败，请重试';redraw()});
  }

  function savePay(){
    if(ui.busy)return;
    const d=ui.draft;
    const it=items.find(i=>i.id===ui.id);
    if(!it)return;
    const x=calc(it,today);
    const amount=r2(d.amount),date=String(d.date||''),note=String(d.note||'').trim();
    let err='';
    if(!/^\d{4}-\d{2}-\d{2}$/.test(date))err='请选择到账日期';
    else if(!(amount>0))err='本次金额要大于 0';
    else if(Math.round(amount*100)>Math.round(x.rem*100))err='本次金额超出未收 '+fmt(x.rem);
    if(err){ui.err=err;redraw();return}
    ui.busy=true;
    const id=it.id,pid=d._id;
    commit(s=>Object.assign({},s,{items:((s&&s.items)||[]).map(i=>{
      if(i.id!==id)return i;
      const ps=i.payments||[];
      if(ps.some(p=>p.id===pid))return i;
